arguments.command:
cd /home/user; ls -la *.pptx; python3 -c "
from pptx import Presentation
from pptx.util import Emu
p=Presentation([f for f in __import__('os').listdir('.') if f.endswith('.pptx')][0])
for i,s in enumerate(p.slides,1):
    print('=== slide',i,'layout',s.slide_layout.name)
    for sh in s.shapes:
        print('  shape',sh.shape_type,sh.name,sh.has_text_frame,sh.left,sh.top,sh.width,sh.height)
        if sh.has_text_frame:
            for para in sh.text_frame.paragraphs:
                print('    para align',para.alignment, 'lvl',para.level, repr(para.text))
                for r in para.runs:
                    f=r.font
                    c=None
                    try: c=f.color.rgb
                    except Exception as e: c=('theme?',f.color.type)
                    print('      run',repr(r.text),'size',f.size,'bold',f.bold,'name',f.name,'color',c)
"

